# with-secrets: environment variable = KeePassXC entry title : field (password or username)
# Only names live here, never values. Entries must be in the group exposed to the Secret Service.

ALPACA_API_KEY    = Alpaca paper : username
ALPACA_SECRET_KEY = Alpaca paper : password

